package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.EnabledVO;

class EnabledValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of enabled of observed source")
  void test_enabled_value_holder_assign_plain_value() {
    Object holder = new Object();
    EnabledValueHolder<Object> value = new EnabledValueHolder<>(holder);
    Assertions.assertSame(holder, value.enabled(true), "Setters must return the holder");
    Assertions.assertTrue(value.getEnabledValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(true, value.getEnabled().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of enabled of observed source")
  void test_enabled_value_holder_assign_value_object() {
    Object holder = new Object();
    EnabledValueHolder<Object> value = new EnabledValueHolder<>(holder);
    EnabledVO vo = EnabledVO.from(true);
    Assertions.assertFalse(value.getEnabledValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.enabled(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getEnabledValue().orElseThrow());
    Assertions.assertSame(holder, value.enabled(Optional.empty()));
    Assertions.assertFalse(value.getEnabledValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.enabled(Optional.of(vo)));
    Assertions.assertSame(vo, value.getEnabledValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of enabled of observed source against the original")
  void test_enabled_value_holder_read() {
    Object holder = new Object();
    EnabledValueHolder<Object> value = new EnabledValueHolder<>(holder);
    EnabledVO vo = EnabledVO.from(true);
    EnabledVO other = EnabledVO.from(true);
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getEnabledValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readEnabled(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readEnabled(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.enabled(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readEnabled(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readEnabled(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of enabled of observed source")
  void test_enabled_value_holder_unset() {
    Object holder = new Object();
    EnabledValueHolder<Object> value = new EnabledValueHolder<>(holder);
    EnabledVO vo = EnabledVO.from(true);
    value.enabled(vo);
    Assertions.assertSame(holder, value.unsetEnabledIfMatches("enabled_other"));
    Assertions.assertTrue(value.getEnabledValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetEnabledIfMatches("enabled"));
    Assertions.assertFalse(value.getEnabledValue().isPresent(),
        "The field name must clear the value");
    value.enabled(vo);
    Assertions.assertSame(holder, value.unsetEnabled());
    Assertions.assertFalse(value.getEnabledValue().isPresent(), "Unset must clear the value");
  }
}
